export const HEAT_MAX=100,HEAT_PER_BOUNCE=5,HEAT_PER_BOOST=9,HEAT_PER_COMBO_STEP=3,HEAT_PER_ULTI=16,HEAT_DECAY_PER_SEC=11,HEAT_PER_HIT_COOLDOWN=18;export function clampHeat(t){return t>0?t>100?100:t:0}export function addHeat(t,e){return clampHeat(t+e)}export function decayHeat(t,e){return clampHeat(t-11*e)}export const BOLT_DAMAGE_BOUNCE=4,BOLT_DAMAGE_BOOST=12,BOLT_DAMAGE_COMBO=8;export function heatDamage(t,e){return Math.round(t*(1+clampHeat(e)/100))}export const PLAYER_MAX_HP=100,HIT_IFRAMES=.9,HITS_TO_MELTDOWN=10,HIT_DAMAGE=PLAYER_MAX_HP/HITS_TO_MELTDOWN,BOSS_PATTERNS=Object.freeze(["aimed","fan","curtain","spiral","rain"]),OPENING_GRACE=2.5,WAVE_TELEGRAPH=1.5,WAVE_REST=2.1,BOSS_MUZZLE_GRACE=.42,CURTAIN_GAP_ORB_DIAMETERS=5;export function waveIntensity(t){return Math.min(1,Math.max(0,t)/8)}export function patternPlan(t,e){const o=waveIntensity(e);switch(BOSS_PATTERNS[t]){case"aimed":return{emits:3+Math.floor(o*3),interval:.7-.18*o};case"fan":return{emits:2+(o>.625?1:0),interval:1.1-.15*o};case"curtain":return{emits:2+(o>.625?1:0),interval:1.3};case"spiral":return{emits:18+Math.floor(o*6),interval:.17};case"rain":return{emits:6,interval:.65-.1*o};default:return{emits:0,interval:1}}}export const INVOKE_BURST_DAMAGE=40,BOSS_AMMO_RISE_PER_SEC=420,VENT_ULTI_ID=100,COOLANT_ULTI_ID=101,VENT_BASE_DAMAGE=60,VENT_DAMAGE_PER_HEAT=4,VENT_SALVO_COUNT=8,COOLANT_DURATION=6,COOLANT_RADIUS=150,BOSS_ULTIS=Object.freeze({[VENT_ULTI_ID]:Object.freeze({name:"VENT",cooldownSeconds:14,color:"#ff8a3c",desc:"Hurls a thermal salvo straight at the boss: heavy base damage plus everything your heat multiplier is worth, then heat resets to zero. The hotter the orb, the bigger the strike."}),[COOLANT_ULTI_ID]:Object.freeze({name:"COOLANT",cooldownSeconds:16,color:"#66e0ff",desc:"A frost shield wraps the army for 6 seconds, dissolving every boss projectile that reaches it. Buys the squad breathing room while your heat climbs back up."})}),BOSS_ULTI_IDS=Object.freeze(Object.keys(BOSS_ULTIS).map(Number));
